// ---------------------------------------------------------------------------
// "Global setup" for the live projects (runs as the `live-setup` project, which
// live / live-webkit depend on — so it never runs for --project=hermetic).
//
// 1. A valid credentials file already exists at credentialsOutputPath() (an
//    earlier local run, or `node setup/merchant-setup.js`) -> nothing to do.
// 2. Otherwise: needs ADMIN_API_KEY + CONNECTOR_AUTH_FILE_PATH, calls
//    ./merchant-setup.js#setupAllCredentials (fresh merchant, one business
//    profile + MCA per connector) and writes the result to
//    credentialsOutputPath() — CREDENTIALS_OUTPUT_PATH or
//    playwright-tests/test-credentials-<env>.json — which the `credentials`
//    fixture reads in every worker.
// ---------------------------------------------------------------------------
import fs from "node:fs";
import path from "node:path";
import { test as setup } from "@playwright/test";
import { HYPERSWITCH_API_URL, TEST_ENV } from "../fixtures/env";
import {
  credentialsOutputPath,
  loadPresetCredentials,
  type Credentials,
} from "../fixtures/credentials";

type SetupModule = {
  setupAllCredentials(args: {
    adminApiKey: string;
    apiBaseUrl: string;
    credsFilePath: string;
  }): Promise<Credentials>;
};

setup("provision live credentials", async () => {
  setup.setTimeout(180_000);

  const preset = loadPresetCredentials(true);
  if (preset) return;

  const adminApiKey = process.env.ADMIN_API_KEY;
  const credsFilePath = process.env.CONNECTOR_AUTH_FILE_PATH;
  if (!adminApiKey) {
    throw new Error(
      "Missing required env var: ADMIN_API_KEY (no pre-provisioned credentials found).\n" +
        `Either export ADMIN_API_KEY + CONNECTOR_AUTH_FILE_PATH, or point CREDENTIALS_OUTPUT_PATH at an existing test-credentials file.`,
    );
  }
  if (!credsFilePath) {
    throw new Error(
      "Missing required env var: CONNECTOR_AUTH_FILE_PATH (path to creds.json).\n" +
        "Example: CONNECTOR_AUTH_FILE_PATH=./creds.json (playwright-tests/creds.json is gitignored)",
    );
  }

  const outPath = credentialsOutputPath();
  // merchant-setup.js also caches to CREDENTIALS_OUTPUT_PATH; pin it to the
  // same file so credentials only ever land in one place.
  process.env.CREDENTIALS_OUTPUT_PATH = outPath;
  process.env.TEST_ENV = TEST_ENV;

  console.log(`[setup] Environment : ${TEST_ENV}`);
  console.log(`[setup] API base URL: ${HYPERSWITCH_API_URL}`);

  // Non-literal require keeps the plain-JS module out of the TypeScript program.
  const merchantSetup = path.join(__dirname, "merchant-setup.js");
  const { setupAllCredentials } = require(merchantSetup) as SetupModule; // eslint-disable-line @typescript-eslint/no-require-imports
  const creds = await setupAllCredentials({
    adminApiKey,
    apiBaseUrl: HYPERSWITCH_API_URL,
    credsFilePath: path.resolve(credsFilePath),
  });
  fs.writeFileSync(outPath, JSON.stringify(creds, null, 2));
  console.log(
    `[setup] Merchant ${creds.merchantId} — credentials written to ${outPath}`,
  );

  if (!loadPresetCredentials()) {
    throw new Error(
      `[setup] ${outPath} was written but is missing required connector profiles; check creds.json.`,
    );
  }
});

// @ts-check
"use strict";

/**
 * Merchant provisioning for the live test tier (plain Node.js, no Playwright).
 *
 * setupAllCredentials() is called once per run by the `live-setup` project
 * (setup/credentials.setup.ts) when no valid credentials file exists. It
 * creates a fresh Hyperswitch merchant account and API key, then for each
 * connector found in creds.json:
 *   1. Creates a dedicated business profile
 *   2. Creates a merchant connector account (MCA) on that profile
 *
 * Returns { publishableKey, secretKey, merchantId, connectorProfileIds } and
 * writes it to the credentials file (see credentialsPath()), which the
 * `credentials` fixture reads in every worker.
 *
 * creds.json format (mirrors juspay/hyperswitch backend test convention):
 * {
 *   "stripe": {
 *     "connector_account_details": { "auth_type": "HeaderKey", "api_key": "sk_test_..." }
 *   },
 *   "adyen": {
 *     "connector_1": {
 *       "connector_account_details": { "auth_type": "SignatureKey", "api_key": "...", ... }
 *     }
 *   }
 * }
 */

const fs = require("fs");
const path = require("path");

// ---------------------------------------------------------------------------
// Per-process cache. Node caches modules, so a second setupAllCredentials()
// call in the same process returns the merchant created by the first one
// instead of provisioning another.
// ---------------------------------------------------------------------------
/** @type {{ publishableKey: string, secretKey: string, merchantId: string, connectorProfileIds: Record<string, string> } | null} */
let _credentialsCache = null;

// ---------------------------------------------------------------------------
// Connector type overrides.
//
// Most connectors are "payment_processor", but some are not:
//   - netcetera: a 3DS authentication server (connector_type: "three_ds_server")
//
// Any connector not listed here defaults to "payment_processor".
// ---------------------------------------------------------------------------
const CONNECTOR_TYPE_MAP = {
  netcetera: "authentication_processor",
};

// ---------------------------------------------------------------------------
// Maps a connector name to the key used in connectorProfileIds.
//
// Most connectors use their own name as the key, but some payment methods
// (like Interac) are provided by multiple sub-connectors (loonie, gigadat)
// that share a single business profile.  The test looks up the profile via
// connectorEnum.INTERAC which maps to the key "interac", so both sub-connectors
// must store their shared profile_id under "interac".
// ---------------------------------------------------------------------------
const PROFILE_KEY_MAP = {
  loonio: "interac",
  gigadat: "interac",
  // Netcetera is an authentication_processor that must share the same
  // business profile as cybersource (the payment_processor). Adding both
  // connectors to the same profile allows 3DS authentication to work.
  netcetera: "cybersource",
};

// ---------------------------------------------------------------------------
// Connectors that require authentication_connector_details to be set on the
// business profile AFTER both the payment processor and auth processor MCAs
// have been created.
//
// Key   = profile key (as stored in connectorProfileIds)
// Value = connector name to register as the authentication_connector
// ---------------------------------------------------------------------------
const AUTH_CONNECTOR_FOR_PROFILE = {
  cybersource: "netcetera",
};

// ---------------------------------------------------------------------------
// Whitelist of connectors actually used by the web SDK e2e tests.
//
// The shared backend creds.json may contain 60+ connectors, but the web SDK
// suite only exercises the ones listed below.  Filtering here avoids
// creating unnecessary business profiles and MCAs on every test run.
