// ---------------------------------------------------------------------------
// API helpers
// ---------------------------------------------------------------------------

/**
 * Creates a new Hyperswitch merchant account.
 * The response includes publishable_key but NOT the secret API key.
 * Use createApiKey() after this to obtain the merchant's secret key.
 *
 * @param {string} adminApiKey
 * @param {string} apiBaseUrl
 * @returns {Promise<{ merchantId: string, publishableKey: string }>}
 */
async function createMerchant(adminApiKey, apiBaseUrl) {
  const merchantId = `test_merchant_${Date.now()}`;
  const maxRetries = 3;
  const retryDelayMs = 5000;

  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    const response = await fetch(`${apiBaseUrl}/accounts`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "api-key": adminApiKey,
      },
      body: JSON.stringify({
        merchant_id:
          attempt > 1 ? `test_merchant_${Date.now()}_${attempt}` : merchantId,
        merchant_name: merchantId,
        locker_id: "m0010",
        merchant_details: {
          primary_contact_person: "Test User",
          primary_email: "test@hyperswitch.io",
        },
        primary_business_details: [
          {
            country: "US",
            business: "default",
          },
        ],
      }),
    });

    if (response.ok) {
      const data = await response.json();
      return {
        merchantId: data.merchant_id,
        publishableKey: data.publishable_key,
      };
    }

    const errorText = await response.text();
    if (attempt < maxRetries && response.status >= 500) {
      console.log(
        `[setup] Merchant creation attempt ${attempt}/${maxRetries} failed (HTTP ${response.status}), retrying in ${retryDelayMs / 1000}s...`,
      );
      await new Promise((resolve) => setTimeout(resolve, retryDelayMs));
      continue;
    }

    throw new Error(
      `[setup] Failed to create merchant: HTTP ${response.status} ${response.statusText}\n${errorText}`,
    );
  }
}

/**
 * Creates an API key for the merchant account.
 * The merchant creation response does NOT include the secret key —
 * it must be created separately via POST /api_keys/:merchant_id.
 *
 * @param {string} adminApiKey
 * @param {string} merchantId
 * @param {string} apiBaseUrl
 * @returns {Promise<string>} The plaintext API key (secret key).
 */
async function createApiKey(adminApiKey, merchantId, apiBaseUrl) {
  const response = await fetch(`${apiBaseUrl}/api_keys/${merchantId}`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "api-key": adminApiKey,
    },
    body: JSON.stringify({
      name: `web_sdk_e2e_key_${Date.now()}`,
      description: "API key for hyperswitch-web e2e test run",
      expiration: "2027-12-31T23:59:59Z",
    }),
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(
      `[setup] Failed to create API key: HTTP ${response.status} ${response.statusText}\n${errorText}`,
    );
  }

  const data = await response.json();
  return data.api_key;
}

/**
 * Creates a dedicated business profile for one connector.
 * @param {string} secretKey
 * @param {string} merchantId
 * @param {string} apiBaseUrl
 * @param {string} connectorName  Used only to generate a meaningful profile name.
 * @returns {Promise<string>}     The new profile_id.
 */
async function createBusinessProfile(
  secretKey,
  merchantId,
  apiBaseUrl,
  connectorName,
) {
  // Append a timestamp to ensure the label is unique across parallel runs.
  const profileName = `${connectorName}_profile_${Date.now()}`;

  const response = await fetch(
    `${apiBaseUrl}/account/${merchantId}/business_profile`,
    {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "api-key": secretKey,
      },
      body: JSON.stringify({
        profile_name: profileName,
        return_url: "http://localhost:9060/completion",
      }),
    },
  );

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(
      `[setup] Failed to create business profile for "${connectorName}": HTTP ${response.status} ${response.statusText}\n${errorText}`,
    );
  }

  const data = await response.json();
  return data.profile_id;
}

/**
 * Patches a business profile to set authentication_connector_details.
 * Required for profiles that have both a payment processor (e.g. cybersource)
 * and an authentication processor (e.g. netcetera).
 *
 * @param {string} secretKey
 * @param {string} merchantId
 * @param {string} profileId
 * @param {string} authConnectorName  e.g. "netcetera"
 * @param {string} apiBaseUrl
 */
async function patchProfileAuthConnector(
  secretKey,
  merchantId,
  profileId,
  authConnectorName,
  apiBaseUrl,
) {
  const response = await fetch(
    `${apiBaseUrl}/account/${merchantId}/business_profile/${profileId}`,
    {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "api-key": secretKey,
      },
      body: JSON.stringify({
        authentication_connector_details: {
          authentication_connectors: [authConnectorName],
          three_ds_requestor_url: "https://sandbox.hyperswitch.io",
        },
      }),
    },
  );

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(
      `[setup] Failed to patch auth connector on profile "${profileId}": HTTP ${response.status} ${response.statusText}\n${errorText}`,
    );
  }
}

/**
 * Creates a merchant connector account (MCA) on the given profile.
 * @param {string} secretKey
 * @param {string} merchantId
 * @param {string} profileId
 * @param {string} connectorName
 * @param {Record<string, string>} connectorAccountDetails  From creds.json.
 * @param {Record<string, any> | undefined} metadata        From creds.json.
 * @param {string} apiBaseUrl
 */
async function createMerchantConnectorAccount(
  secretKey,
  merchantId,
  profileId,
  connectorName,
  connectorAccountDetails,
  metadata,
  apiBaseUrl,
) {
  const paymentMethodsEnabled =
    CONNECTOR_PAYMENT_METHODS[connectorName] ||
    CONNECTOR_PAYMENT_METHODS.default;
  const connectorType =
    CONNECTOR_TYPE_MAP[connectorName] || "payment_processor";

  const requestBody = {
    connector_type: connectorType,
    connector_name: connectorName,
    connector_label: `${connectorName}_${Date.now()}`,
    profile_id: profileId,
    connector_account_details: connectorAccountDetails,
    payment_methods_enabled: paymentMethodsEnabled,
    test_mode: true,
    disabled: false,
  };

  // Pass metadata from creds.json if present (e.g. cybersource needs
  // google_pay, apple_pay_combined, acquirer_bin, acquirer_merchant_id).
  // Some connectors (e.g. klarna) require the metadata field to be present
  // even when empty, so we default to {}.
  requestBody.metadata = metadata || {};

  const response = await fetch(
    `${apiBaseUrl}/account/${merchantId}/connectors`,
    {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "api-key": secretKey,
      },
      body: JSON.stringify(requestBody),
    },
  );

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(
      `[setup] Failed to create MCA for "${connectorName}": HTTP ${response.status} ${response.statusText}\n${errorText}`,
    );
  }
}

// ---------------------------------------------------------------------------
// creds.json parser
// ---------------------------------------------------------------------------

/**
 * Extracts connector_account_details from a creds.json entry.
 * Handles both direct and nested (connector_1 / connector_2) formats.
 *
 * Direct:   { "connector_account_details": { ... } }
 * Nested:   { "connector_1": { "connector_account_details": { ... } } }
 *
 * @param {Record<string, any>} connectorCreds
 * @returns {Record<string, string> | null}
 */
function extractConnectorAccountDetails(connectorCreds) {
  if (connectorCreds.connector_account_details) {
    return connectorCreds.connector_account_details;
  }
  if (
    connectorCreds.connector_1 &&
    connectorCreds.connector_1.connector_account_details
  ) {
    return connectorCreds.connector_1.connector_account_details;
  }
  return null;
}

/**
 * Extracts metadata from a creds.json entry.
 * Handles both direct and nested (connector_1 / connector_2) formats.
 *
 * @param {Record<string, any>} connectorCreds
 * @returns {Record<string, any> | undefined}
 */
function extractMetadata(connectorCreds) {
  if (connectorCreds.metadata) {
    return connectorCreds.metadata;
  }
  if (connectorCreds.connector_1 && connectorCreds.connector_1.metadata) {
    return connectorCreds.connector_1.metadata;
  }
  return undefined;
}

// ---------------------------------------------------------------------------
// Main orchestrator
// ---------------------------------------------------------------------------

/**
 * Creates a fresh merchant + per-connector business profiles + MCAs, and
 * writes the result to credentialsPath().
 *
 * @param {{ adminApiKey: string, apiBaseUrl: string, credsFilePath: string }} params
 * @returns {Promise<{
 *   publishableKey: string,
 *   secretKey: string,
 *   merchantId: string,
 *   connectorProfileIds: Record<string, string>
 * }>}
 */
async function setupAllCredentials({ adminApiKey, apiBaseUrl, credsFilePath }) {
  // ── Cache check ───────────────────────────────────────────────────────────
  // Only the first call in a process makes real API calls.
  if (_credentialsCache) {
    console.log(
      "[setup] Returning cached credentials (merchant already created for this run).",
    );
    return _credentialsCache;
  }

  // ── 1. Read and parse creds.json ─────────────────────────────────────────
  const absoluteCredsPath = path.isAbsolute(credsFilePath)
    ? credsFilePath
    : path.resolve(process.cwd(), credsFilePath);

  if (!fs.existsSync(absoluteCredsPath)) {
    throw new Error(
      `[setup] creds.json not found at: ${absoluteCredsPath}\n` +
        `Set CONNECTOR_AUTH_FILE_PATH ` +
        `to the path of your creds.json file.`,
    );
  }

  const credsJson = JSON.parse(fs.readFileSync(absoluteCredsPath, "utf-8"));
  console.log(
    `[setup] Loaded creds.json with connectors: ${Object.keys(credsJson)
      .filter((k) => k !== "Configs")
      .join(", ")}`,
  );

  // ── 2. Create merchant ───────────────────────────────────────────────────
  console.log(`[setup] Creating merchant on ${apiBaseUrl} ...`);
  const { merchantId, publishableKey } = await createMerchant(
    adminApiKey,
    apiBaseUrl,
  );
  console.log(`[setup] Merchant created → merchant_id: ${merchantId}`);

  // ── 2b. Create API key for the merchant ─────────────────────────────────
  // The merchant creation response does not include the secret key.
  // It must be created separately via POST /api_keys/:merchant_id.
  const secretKey = await createApiKey(adminApiKey, merchantId, apiBaseUrl);
  console.log(`[setup] API key created for merchant`);

  // ── 3. For each connector: create profile + MCA ──────────────────────────
  const connectorProfileIds = {};

  for (const [connectorName, connectorCreds] of Object.entries(credsJson)) {
    // Skip top-level "Configs" key (dynamic config metadata, not a connector)
    if (connectorName === "Configs" || typeof connectorCreds !== "object") {
      continue;
    }

    // Skip connectors not used by any web SDK e2e test to avoid
    // provisioning unnecessary business profiles and MCAs.
    if (!REQUIRED_CONNECTORS.includes(connectorName)) {
      console.log(
        `[setup] Skipping "${connectorName}" — not required by the web SDK e2e tests.`,
      );
      continue;
    }

    const accountDetails = extractConnectorAccountDetails(connectorCreds);
    if (!accountDetails) {
      console.warn(
        `[setup] Skipping "${connectorName}": no connector_account_details found.`,
      );
      continue;
    }

    const metadata = extractMetadata(connectorCreds);

    try {
      // Determine the profile key — most connectors use their own name,
      // but sub-connectors like loonie/gigadat share a profile keyed as "interac".
      const profileKey = PROFILE_KEY_MAP[connectorName] || connectorName;

      // a) Create a new business profile, or reuse an existing one if a
      //    sub-connector already created it (e.g. gigadat reuses loonie's profile).
      let profileId = connectorProfileIds[profileKey];
      if (!profileId) {
        profileId = await createBusinessProfile(
          secretKey,
          merchantId,
          apiBaseUrl,
          connectorName,
        );
      }

      // b) MCA on that profile
      await createMerchantConnectorAccount(
        secretKey,
        merchantId,
        profileId,
        connectorName,
        accountDetails,
        metadata,
        apiBaseUrl,
      );

      connectorProfileIds[profileKey] = profileId;
      // Also expose netcetera under its own key so tests can look it up
      // via connectorEnum.NETCETERA ("netcetera") directly.
      if (profileKey !== connectorName) {
        connectorProfileIds[connectorName] = profileId;
      }
      console.log(
        `[setup] ${connectorName.padEnd(20)} → profile_id: ${profileId}` +
          (profileKey !== connectorName ? ` (shared as "${profileKey}")` : ""),
      );
    } catch (err) {
      // Log the error but continue with remaining connectors. The failed
      // connector gets no profile_id: specs that require it fail fast in
      // their beforeEach (e.g. Redsys, Netcetera), while specs for optional
      // connectors (e.g. Mifinity, Juspay) skip with a reason.
      console.error(
        `[setup] Error setting up "${connectorName}":`,
        err.message,
      );
    }
  }

  console.log(
    `[setup] Done. ${Object.keys(connectorProfileIds).length} connector(s) configured.`,
  );

  // ── Patch authentication_connector_details on profiles that need it ───────
  // Must run AFTER all MCAs are created so the auth connector MCA exists.
  for (const [profileKey, authConnector] of Object.entries(
    AUTH_CONNECTOR_FOR_PROFILE,
  )) {
    const profileId = connectorProfileIds[profileKey];
    if (!profileId) {
      console.warn(
        `[setup] Skipping auth connector patch for "${profileKey}": profile not found.`,
      );
      continue;
    }
    try {
      await patchProfileAuthConnector(
        secretKey,
        merchantId,
        profileId,
        authConnector,
        apiBaseUrl,
      );
      console.log(
        `[setup] Patched profile ${profileId} with authentication_connector: ${authConnector}`,
      );
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      console.error(
        `[setup] Error patching auth connector for "${profileKey}":`,
        msg,
      );
    }
  }

  _credentialsCache = {
    publishableKey,
    secretKey,
    merchantId,
    connectorProfileIds,
  };

  const cachePath = credentialsPath();
  try {
    fs.writeFileSync(cachePath, JSON.stringify(_credentialsCache, null, 2));
    console.log(
      `[setup] Credentials cached to ${cachePath} for reuse by subsequent runs.`,
    );
  } catch (err) {
    console.warn(`[setup] Could not cache credentials: ${err.message}`);
  }

  return _credentialsCache;
}

/**
 * Where credentials are written: CREDENTIALS_OUTPUT_PATH when set, otherwise
 * playwright-tests/test-credentials-<TEST_ENV>.json (gitignored). Must agree
 * with credentialsOutputPath() in fixtures/credentials.ts, which reads it.
 *
 * @returns {string}
 */
function credentialsPath() {
  return process.env.CREDENTIALS_OUTPUT_PATH
    ? path.resolve(process.env.CREDENTIALS_OUTPUT_PATH)
    : path.join(
        __dirname,
        "..",
        `test-credentials-${process.env.TEST_ENV || "sandbox"}.json`,
      );
}

module.exports = { setupAllCredentials };

// ---------------------------------------------------------------------------
// Standalone CLI entry point — a local convenience for pre-provisioning a
// merchant without running any tests (the `live-setup` project does the same
// thing automatically when no credentials file exists).
//
//   TEST_ENV=sandbox HYPERSWITCH_API_URL=https://sandbox.hyperswitch.io \
//   ADMIN_API_KEY=... CONNECTOR_AUTH_FILE_PATH=./creds.json \
//   node setup/merchant-setup.js
//
// Reads env vars:
//   ADMIN_API_KEY             — Hyperswitch admin key
//   HYPERSWITCH_API_URL       — target API base URL (sandbox / integ / local)
//   CONNECTOR_AUTH_FILE_PATH  — path to creds.json
//   TEST_ENV                  — names the default output file (default sandbox)
//   CREDENTIALS_OUTPUT_PATH   — optional; overrides the output file
//
// Writes { publishableKey, secretKey, merchantId, connectorProfileIds } to
// credentialsPath(), where the live projects pick it up and skip provisioning.
// ---------------------------------------------------------------------------
if (require.main === module) {
  (async () => {
    const adminApiKey = process.env.ADMIN_API_KEY;
    const apiBaseUrl = process.env.HYPERSWITCH_API_URL;
    const credsFilePath = process.env.CONNECTOR_AUTH_FILE_PATH;
    const outputPath = credentialsPath();

    if (!adminApiKey) {
      console.error("[setup] Missing ADMIN_API_KEY env var.");
      process.exit(1);
    }
    if (!apiBaseUrl) {
      console.error("[setup] Missing HYPERSWITCH_API_URL env var.");
      process.exit(1);
    }
    if (!credsFilePath) {
      console.error("[setup] Missing CONNECTOR_AUTH_FILE_PATH env var.");
      process.exit(1);
    }

    try {
      const creds = await setupAllCredentials({
        adminApiKey,
        apiBaseUrl,
        credsFilePath,
      });
      fs.writeFileSync(outputPath, JSON.stringify(creds, null, 2));
      console.log(`[setup] Credentials written to ${outputPath}`);
    } catch (err) {
      console.error("[setup] Fatal error:", err.message);
      process.exit(1);
    }
  })();
}

// ---------------------------------------------------------------------------
// Merchant credentials for the live tier.
//
// One file, credentialsOutputPath():
//   CREDENTIALS_OUTPUT_PATH when set (CI points it outside the workspace),
//   otherwise playwright-tests/test-credentials-<TEST_ENV>.json (gitignored).
// A file is only accepted when it carries profile IDs for every connector in
// requiredPresetProfileIds; otherwise it is ignored as stale.
//
// When the file is missing or stale, the `live-setup` project
// (setup/credentials.setup.ts) provisions a merchant with
// setup/merchant-setup.js#setupAllCredentials and writes it there.
//
// The hermetic tier never reads any of this: it uses HERMETIC_CREDENTIALS.
// ---------------------------------------------------------------------------
import fs from "node:fs";
import path from "node:path";
import { PW_ROOT, TEST_ENV, requiredPresetProfileIds } from "./env";
import { connectorEnum, type Connector } from "./connectors";

export interface Credentials {
  publishableKey: string;
  secretKey: string;
  merchantId: string;
  connectorProfileIds: Record<string, string>;
}

/** The file the setup project writes and the live tier reads. */
export const credentialsOutputPath = (): string =>
  process.env.CREDENTIALS_OUTPUT_PATH
    ? path.resolve(process.env.CREDENTIALS_OUTPUT_PATH)
    : path.join(PW_ROOT, `test-credentials-${TEST_ENV}.json`);

export interface LoadedCredentials {
  credentials: Credentials;
  path: string;
}

/** Returns the pre-provisioned credentials file if it exists and is valid, or null. Never throws. */
export function loadPresetCredentials(log = false): LoadedCredentials | null {
  const file = credentialsOutputPath();
  if (!fs.existsSync(file)) return null;
  try {
    const parsed = JSON.parse(fs.readFileSync(file, "utf-8")) as Credentials;
    const missing = requiredPresetProfileIds.filter(
      (c) => !parsed.connectorProfileIds?.[c],
    );
    if (missing.length > 0) {
      if (log)
        console.warn(
          `[playwright] Ignoring stale credentials at ${file}: missing profile IDs for ${missing.join(", ")}.`,
        );
      return null;
    }
    if (log)
      console.log(
        `[playwright] Using credentials at ${file} (merchant ${parsed.merchantId})`,
      );
    return { credentials: parsed, path: file };
  } catch (err) {
    if (log)
      console.warn(
        `[playwright] Failed to parse ${file}: ${(err as Error).message}`,
      );
    return null;
  }
}

/**
 * Fake, clearly-non-secret credentials used by the hermetic tier. Every
 * connector in connectorEnum gets a deterministic profile ID so specs can keep
 * using `credentials.profileId(connectorEnum.X)` unchanged.
 */
export const HERMETIC_CREDENTIALS: Credentials = {
  publishableKey: "pk_snd_hermetic0000000000000000000000",
  secretKey: "snd_hermetic_not_a_real_key",
  merchantId: "merchant_hermetic",
  connectorProfileIds: Object.fromEntries(
    Object.values(connectorEnum).map((c) => [c, `pro_hermetic_${c}`]),
  ),
};

/** Credentials plus a per-connector profile ID lookup. */
export class TestCredentials implements Credentials {
  readonly publishableKey: string;
  readonly secretKey: string;
  readonly merchantId: string;
  readonly connectorProfileIds: Record<string, string>;

  constructor(c: Credentials) {
    this.publishableKey = c.publishableKey;
    this.secretKey = c.secretKey;
    this.merchantId = c.merchantId;
    this.connectorProfileIds = { ...c.connectorProfileIds };
  }

  /** Profile ID of the business profile provisioned for `connector` (undefined if absent). */
  profileId(connector: Connector): string | undefined {
    return this.connectorProfileIds[connector];
  }

  /** Default profile used when a payment body has no profile_id (the Stripe profile). */
  get defaultProfileId(): string {
    return this.connectorProfileIds[connectorEnum.STRIPE] ?? "";
  }
}

// ---------------------------------------------------------------------------
// Node-side router calls (create intent, retrieve, poll status, payment
// methods). In the hermetic tier nothing leaves the machine: every call is
// answered by the same hermetic engine that serves the browser.
//
// Live calls use Node's global fetch, NOT Playwright's APIRequestContext: the
// latter records every request (with its `api-key` header, i.e. the merchant's
// secret key) in traces and the HTML report that CI uploads. `callLog` keeps a redacted summary instead (attached on failure).
// ---------------------------------------------------------------------------
import { expect } from "@playwright/test";
import { HYPERSWITCH_API_URL } from "./env";
import type { TestCredentials } from "./credentials";
import type { Hermetic } from "./hermetic";
import type { PaymentBody } from "./payment-body";

export interface PaymentIntent {
  paymentId: string;
  clientSecret: string;
  /** profile_id the intent was created on (default: Stripe profile). */
  profileId: string;
  /** The exact body sent to POST /payments. */
  body: PaymentBody;
  /** Router response (hermetic: the fake intent). */
  response: Record<string, unknown>;
}

type Json = Record<string, any>; // eslint-disable-line @typescript-eslint/no-explicit-any

/** Masks client secrets (`…_secret_<random>`) in a URL/path for logs and reports. */
export const redactClientSecrets = (s: string): string =>
  s.replace(/(_secret_)[A-Za-z0-9]+/g, "$1***");

export interface ApiCallLogEntry {
  method: string;
  /** Path + query, client secrets masked. */
  path: string;
  /** "publishable" or "secret" (never the key itself). */
  key: "publishable" | "secret" | "other";
  status: number;
  ms: number;
}

export class HyperswitchApi {
  /** Redacted log of live router calls made by this test (empty in hermetic mode). */
  readonly callLog: ApiCallLogEntry[] = [];

  constructor(
    private readonly credentials: TestCredentials,
    private readonly hermetic: Hermetic,
    readonly baseUrl: string = HYPERSWITCH_API_URL,
  ) {}

  /**
   * Low-level call. Hermetic: served from recordings; no matching route answers
   * 404 JSON and is logged in `hermetic.unmatched`, which fails the test.
   */
  async call(
    method: "GET" | "POST",
    path: string,
    {
      apiKey = this.credentials.secretKey,
      data,
    }: { apiKey?: string; data?: unknown } = {},
  ): Promise<{ status: number; body: Json }> {
    const url = `${this.baseUrl}${path}`;
    if (this.hermetic.enabled) {
      const engine = this.hermetic.engine!;
      const served = await engine.serve(method, url, data);
      if (!served) {
        engine.recordUnmatched(method, new URL(url), data, 404);
        return {
          status: 404,
          body: {
            error: { type: "hermetic_unmatched", message: `${method} ${path}` },
          },
        };
      }
      return { status: served.status, body: (served.body ?? {}) as Json };
    }
    const key =
      apiKey === this.credentials.secretKey
        ? "secret"
        : apiKey === this.credentials.publishableKey
          ? "publishable"
          : "other";
    const started = Date.now();
    let response: Response;
    try {
      response = await fetch(url, {
        method,
        headers: {
          "Content-Type": "application/json",
          Accept: "application/json",
          "api-key": apiKey,
        },
        body: data === undefined ? undefined : JSON.stringify(data),
        signal: AbortSignal.timeout(60_000),
      });
    } catch (err) {
      // Never let the URL (client secret) or headers (api key) into the error.
      throw new Error(
        `[api] ${method} ${redactClientSecrets(path)} failed: ${(err as Error).message}`,
      );
    }
    const text = await response.text();
    let body: Json = {};
    try {
      body = text ? JSON.parse(text) : {};
    } catch {
      body = { raw: text };
    }
    this.callLog.push({
      method,
      path: redactClientSecrets(path),
      key,
      status: response.status,
      ms: Date.now() - started,
    });
    return { status: response.status, body };
  }

  /**
   * POST /payments with the secret key; fills profile_id with the Stripe profile when the body has none.
   * Hermetic: no network — returns a fake payment_id/client_secret that the
   * recordings are templated with.
   */
  async createPaymentIntent(body: PaymentBody): Promise<PaymentIntent> {
    const finalBody: PaymentBody = structuredClone(body);
    if (!finalBody.profile_id)
      finalBody.profile_id = this.credentials.defaultProfileId;

    if (this.hermetic.enabled) {
      const intent = this.hermetic.engine!.createIntent(finalBody);
      return {
        paymentId: intent.payment_id,
        clientSecret: intent.client_secret,
        profileId: intent.profile_id,
        body: finalBody,
        response: { ...intent },
      };
    }

    const { status, body: res } = await this.call("POST", "/payments", {
      data: finalBody,
    });
    expect(
      res,
      `POST /payments failed (${status}): ${JSON.stringify(res).slice(0, 500)}`,
    ).toHaveProperty("client_secret");
    const intent: PaymentIntent = {
      paymentId: res.payment_id,
      clientSecret: res.client_secret,
      profileId: res.profile_id ?? finalBody.profile_id ?? "",
      body: finalBody,
      response: res,
    };
    this.hermetic.noteLiveIntent(intent);
    return intent;
  }

  /** GET /payments/:id (force_sync by default) with the secret key. */
  async retrievePayment(
    paymentId: string,
    { forceSync = true } = {},
  ): Promise<Json> {
    const path = `/payments/${paymentId}${forceSync ? "?force_sync=true" : ""}`;
    const { body } = await this.call("GET", path);
    if (body?.error?.type === "hermetic_unmatched") {
      throw new Error(
        `[hermetic] GET ${path}: no fixture route answered (base "retrieve" is ` +
          `GET /payments/:paymentId; check the spec's recordings)`,
      );
    }
    return body;
  }

  /**
   * Polls GET /payments/:id?force_sync=true every
   * `intervalMs` until status === expectedStatus, failing after `timeoutMs`.
   * Hermetic: reads the status the recordings put on the intent (confirm's intentPatch).
   */
  async pollPaymentStatus(
    paymentId: string,
    expectedStatus: string,
    {
      timeoutMs = 20_000,
      intervalMs = 2_000,
    }: { timeoutMs?: number; intervalMs?: number } = {},
  ): Promise<Json> {
    const deadline = Date.now() + timeoutMs;
    for (;;) {
      const payment = await this.retrievePayment(paymentId);
      if (payment.status === expectedStatus) return payment;
      if (Date.now() >= deadline) {
        throw new Error(
          `Payment did not reach "${expectedStatus}" within ${timeoutMs} ms. Last status: ${payment.status}`,
        );
      }
      await new Promise((r) =>
        setTimeout(r, this.hermetic.enabled ? 100 : intervalMs),
      );
    }
  }

  /** GET /payments/:id/client — what the SDK renders from (payment_methods_enabled, saved methods). */
  async clientList(paymentId: string, clientSecret: string): Promise<Json> {
    const { body } = await this.call(
      "GET",
      `/payments/${paymentId}/client?client_secret=${clientSecret}`,
      { apiKey: this.credentials.publishableKey },
    );
    return body;
  }

  /** Legacy GET /account/payment_methods (nested payment_methods with required_fields). */
  async accountPaymentMethods(clientSecret: string): Promise<Json> {
    const { body } = await this.call(
      "GET",
      `/account/payment_methods?client_secret=${clientSecret}`,
      {
        apiKey: this.credentials.publishableKey,
      },
    );
    return body;
  }

  /** required_fields of card/<cardType> from the legacy list (input for sdk.testDynamicFields()). */
  async cardRequiredFields(
    clientSecret: string,
    cardType = "debit",
  ): Promise<Record<string, unknown>> {
    const list = await this.accountPaymentMethods(clientSecret);
    const card = (list.payment_methods ?? []).find(
      (pm: Json) => pm.payment_method === "card",
    );
    const type = card?.payment_method_types?.find(
      (t: Json) => t.payment_method_type === cardType,
    );
    return type?.required_fields ?? {};
  }

  /** One-line summary of payment_methods_enabled, for skip/debug logs. */
  async describePaymentMethods(
    paymentId: string,
    clientSecret: string,
  ): Promise<string> {
    const list = await this.clientList(paymentId, clientSecret).catch(
      () => ({}) as Json,
    );
    const pms = (list.payment_methods_enabled ?? []) as Json[];
    return (
      pms
        .map((pm) => `${pm.payment_method}/${pm.payment_method_type}`)
        .join(" | ") || "(empty)"
    );
  }
}

// ---------------------------------------------------------------------------
// Payment-element helpers: frame lookup, card entry, payment method selection,
// overlays and dynamic fields inside the SDK iframes.
//
// Frame layout of the demo shop:
//   page
//   ├─ #orca-payment-element-iframeRef-orca-elements-payment-element-payment-element  (paymentElement)
//   │    payment method tabs/list/dropdown, billing & dynamic fields, saved methods, "Add new card"
//   │  └─ iframe[id^="orca-payment-element-iframeRef-"][src*="componentName=paymentMethodsSDK"]
//   │       (cardFields, the "vault" iframe) card number / expiry / CVC inputs and their
//   │       ".Error.pt-1" messages; saved-card CVC lives in a second such iframe
//   └─ #orca-fullscreen (3DS / QR / voucher overlays)  -> nestedIFrame(selector)
//
// Some elements render in the outer frame or the card frame depending on the
// payment method and layout. Playwright cannot put frame locators inside
// Locator.or(), so:
//   sdk.field(testId)       sync; routes card-input test ids to cardFields, the rest to paymentElement
//   sdk.cardErrors          ".Error.pt-1" inside the card iframe
//   await sdk.locate(sel)   async; resolves a CSS selector in whichever frame has it (either frame)
//   await sdk.locateTestId(id)  same for a data-testid
// ---------------------------------------------------------------------------
import {
  expect,
  test,
  type FrameLocator,
  type Locator,
  type Page,
} from "@playwright/test";
import type { CardDetails } from "./cards";
import type { CustomerData } from "./types";
import { testIds } from "./test-ids";

export const PAYMENT_ELEMENT_IFRAME =
  "#orca-payment-element-iframeRef-orca-elements-payment-element-payment-element";
export const CARD_FIELDS_IFRAME =
  'iframe[id^="orca-payment-element-iframeRef-"][src*="componentName=paymentMethodsSDK"]';
export const FULLSCREEN_IFRAME = "#orca-fullscreen";

/** Display name -> <select data-testid="paymentMethodsSelect"> option value. */
export const PAYMENT_METHOD_SELECT_VALUES: Record<string, string> = {
  iDEAL: "ideal",
  EPS: "eps",
  Blik: "blik",
  Interac: "interac",
  Mifinity: "mifinity",
  Crypto: "crypto_currency",
  "Cash / Voucher": "classic",
  "E-Voucher": "evoucher",
  AlipayHK: "ali_pay_hk",
  DuitNow: "duit_now",
  "Bancontact Card": "bancontact_card",
  "SEPA Bank Transfer": "sepa_bank_transfer",
  "Online Banking Fpx": "online_banking_fpx",
  "Pay by Bank": "open_banking_uk",
  Klarna: "klarna",
  Trustly: "trustly",
  Card: "card",
};

export const PAYMENT_METHOD_WAIT_MS = 15_000;

/** data-testids rendered inside the card ("vault") iframe rather than the outer payment element. */
export const CARD_FRAME_TEST_IDS: ReadonlySet<string> = new Set([
  testIds.cardNoInputTestId,
  testIds.expiryInputTestId,
  testIds.cardCVVInputTestId,
]);

export interface SelectOrSkipOptions {
  /** How long to wait for the method to be offered before skipping (live) or failing (hermetic). Default 15 s. */
  timeout?: number;
  /** Called before skipping or failing, e.g. to log the payment_methods_enabled the router returned. */
  onMissing?: (visibleText: string) => Promise<void> | void;
}

export class Sdk {
  /** Outer payment element iframe. */
  readonly paymentElement: FrameLocator;
  /** Inner card-fields iframe (card number / expiry / CVC live here). */
  readonly cardFields: FrameLocator;

  /**
   * @param debugPaymentMethods optional: returns a one-line summary of the router's
   *   payment_methods_enabled, logged when selectPaymentMethodOrSkip() skips
   *   (wired by the `sdk` fixture).
   * @param hermetic true on the hermetic project: a payment method that is not
   *   offered fails selectPaymentMethodOrSkip() instead of skipping.
   */
  constructor(
    readonly page: Page,
    private readonly debugPaymentMethods?: () => Promise<string>,
    private readonly hermetic = false,
  ) {
    this.paymentElement = page.frameLocator(PAYMENT_ELEMENT_IFRAME);
    // First *visible* inner iframe: the new-card form, or the saved-card CVC
    // iframe when the saved-methods screen is showing.
    this.cardFields = this.paymentElement
      .locator(CARD_FIELDS_IFRAME)
      .filter({ visible: true })
      .first()
      .contentFrame();
  }

  // ── Lookup ───────────────────────────────────────────────────────────────

  /**
   * Element with data-testid=`testId`. Card number/expiry/CVC resolve in the
   * card iframe, everything else in the outer payment element. Use
   * `locateTestId()` when you don't know which frame renders it.
   */
  field(testId: string): Locator {
    return CARD_FRAME_TEST_IDS.has(testId)
      ? this.cardFields.getByTestId(testId)
      : this.paymentElement.getByTestId(testId);
  }

  /** CSS selector in the outer payment element. */
  find(selector: string): Locator {
    return this.paymentElement.locator(selector);
  }

  /** CSS selector in the card iframe. */
  findInCard(selector: string): Locator {
    return this.cardFields.locator(selector);
  }

  /** Text in the outer payment element. */
  text(text: string | RegExp, options?: { exact?: boolean }): Locator {
    return this.paymentElement.getByText(text, options);
  }

  /**
   * "Either frame" lookup: polls both frames until one contains
   * `selector` and returns that frame's locator. Falls back to the outer frame
   * after `timeout` so a following assertion fails with a readable message (and
   * `not.toBeVisible()` style assertions still work).
   */
  async locate(selector: string, { timeout = 10_000 } = {}): Promise<Locator> {
    const candidates = [
      this.cardFields.locator(selector),
      this.paymentElement.locator(selector),
    ];
    const deadline = Date.now() + timeout;
    for (;;) {
      for (const c of candidates) {
        if ((await c.count().catch(() => 0)) > 0) return c;
      }
      if (Date.now() >= deadline) return candidates[1];
      await new Promise((r) => setTimeout(r, 100));
    }
  }

  /** `locate()` for a data-testid. */
  async locateTestId(
    testId: string,
    opts?: { timeout?: number },
  ): Promise<Locator> {
    return this.locate(`[data-testid="${testId}"]`, opts);
  }

  /** Card-field validation messages (".Error.pt-1" inside the card iframe). */
  get cardErrors(): Locator {
    return this.cardFields.locator(".Error.pt-1");
  }

  /** Validation messages of non-card fields (".Error.pt-1" in the outer frame, e.g. billing). */
  get formErrors(): Locator {
    return this.paymentElement.locator(".Error.pt-1");
  }

  /** The demo shop's "Pay now" button (top-level page, not inside the SDK). */
  get submitButton(): Locator {
    return this.page.locator("#submit");
  }

  // ── Readiness ────────────────────────────────────────────────────────────

  /** Waits until the outer iframe, the inner card iframe and the card number input exist. */
  async waitForReady({ timeout = 15_000 } = {}): Promise<void> {
    await expect(this.page.locator(PAYMENT_ELEMENT_IFRAME)).toBeAttached({
      timeout,
    });
    await expect(
      this.cardFields.getByTestId(testIds.cardNoInputTestId),
    ).toBeAttached({ timeout });
  }

  // ── Typing ───────────────────────────────────────────────────────────────

  /** Types key by key into the field, appending to what is there (no clearing). */
  async type(testId: string, text: string, { delay = 0 } = {}): Promise<void> {
    await this.field(testId).pressSequentially(text, { delay });
  }

  /** Waits until visible and enabled, clears, then types with a 50 ms key delay. */
  async safeType(
    testId: string,
    text: string,
    { delay = 50 } = {},
  ): Promise<void> {
    const f = this.field(testId);
    await expect(f).toBeVisible();
    await expect(f).toBeEnabled();
    await f.clear();
    await f.pressSequentially(text, { delay });
  }

  /** Card number, expiry (MMYY) and CVC, each via safeType() (clears first). */
  async enterCardDetails(card: CardDetails): Promise<void> {
    await this.safeType(testIds.cardNoInputTestId, card.cardNo);
    await this.safeType(
      testIds.expiryInputTestId,
      card.card_exp_month + card.card_exp_year,
    );
    await this.safeType(testIds.cardCVVInputTestId, card.cvc);
  }

  /** Clicks the demo shop's "Pay now" (#submit). */
  async submit(): Promise<void> {
    await this.submitButton.click();
  }

  /** waitForReady() + enterCardDetails() + submit(). Assert the outcome in the test. */
  async payWithCard(card: CardDetails): Promise<void> {
    await this.waitForReady();
    await this.enterCardDetails(card);
    await this.submit();
  }

  // ── Payment method selection ─────────────────────────────────────────────

  /** Clicks "Add new card" if the saved-methods screen is showing. */
  async clickAddNewCardIfPresent(): Promise<boolean> {
    const addNew = this.field(testIds.addNewCardIcon);
    if (await addNew.count()) {
      await addNew.first().click();
      return true;
    }
    return false;
  }

  /**
   * If saved cards are shown, clicks "Add new card" first; then clicks the
   * payment method by its visible name.
   */
  async selectPaymentMethod(methodName: string): Promise<void> {
    await this.clickAddNewCardIfPresent();
    await this.text(methodName).first().click();
  }

  /**
   * Waits up to 15 s for `methodName` to be offered. If it never appears, a live
   * test is SKIPPED with a named reason (the merchant may not have the method
   * provisioned); a hermetic test FAILS, because the recordings fix the payment
   * methods, so a missing one is an SDK regression or a fixture bug. When
   * offered, clicks the tab (`button.Tab`) or, when the method sits in the
   * "more" dropdown, selects it in `paymentMethodsSelect` via the display-name
   * -> value map.
   */
  async selectPaymentMethodOrSkip(
    methodName: string,
    opts: SelectOrSkipOptions = {},
  ): Promise<void> {
    const timeout = opts.timeout ?? PAYMENT_METHOD_WAIT_MS;
    await this.clickAddNewCardIfPresent();

    const bodyText = async () => {
      const texts = await Promise.all([
        this.paymentElement
          .locator("body")
          .textContent({ timeout: 1_000 })
          .catch(() => ""),
        this.cardFields
          .locator("body")
          .textContent({ timeout: 1_000 })
          .catch(() => ""),
      ]);
      return texts.map((t) => t ?? "").join(" ");
    };

    let offered = false;
    try {
      await expect
        .poll(async () => (await bodyText()).includes(methodName), {
          timeout,
          intervals: [500],
        })
        .toBe(true);
      offered = true;
    } catch {
      offered = false;
    }

    if (!offered) {
      const visible = (await bodyText())
        .replace(/\s+/g, " ")
        .trim()
        .slice(0, 300);
      const summary = this.debugPaymentMethods
        ? await this.debugPaymentMethods().catch((e) => `(unavailable: ${e})`)
        : "(unavailable)";
      await opts.onMissing?.(visible);
      if (this.hermetic) {
        throw new Error(
          `Payment method "${methodName}" is not offered after ${timeout}ms. The hermetic ` +
            `recordings fix the payment methods, so this is an SDK regression or a fixture bug.\n` +
            `payment_methods_enabled: ${summary}\nSDK iframe text: "${visible}"`,
        );
      }
      console.log(
        `[skip] "${methodName}" not found after ${timeout}ms. SDK iframe text: "${visible}"`,
      );
      console.log(`[debug] payment_methods_enabled: ${summary}`);
      test.skip(
        true,
        `Payment method "${methodName}" is not offered by the SDK for this profile/amount`,
      );
      return;
    }

    const tab = this.paymentElement
      .locator("button.Tab")
      .filter({ hasText: methodName });
    if (await tab.count()) {
      await this.text(methodName).first().click({ force: true });
      return;
    }
    const value =
      PAYMENT_METHOD_SELECT_VALUES[methodName] ?? methodName.toLowerCase();
    const select = this.field(testIds.paymentMethodDropDownTestId);
    await expect(select).toBeAttached();
    await select.selectOption(value, { force: true });
  }

  // ── Overlays ─────────────────────────────────────────────────────────────

  /** A frame inside #orca-fullscreen (3DS / QR / voucher overlays), once it is visible and has content. */
  async nestedIFrame(
    selector: string,
    { timeout = 15_000 } = {},
  ): Promise<FrameLocator> {
    await expect(this.page.locator(FULLSCREEN_IFRAME)).toBeVisible({ timeout });
    const fullscreen = this.page.frameLocator(FULLSCREEN_IFRAME);
    await expect(fullscreen.locator(selector)).toBeVisible({ timeout });
    const nested = fullscreen.frameLocator(selector);
    await expect(nested.locator("body")).not.toBeEmpty({ timeout });
    return nested;
  }

  // ── Dynamic fields ───────────────────────────────────────────────────────

  /**
   * Fills every field the router lists as required
   * for card/debit (legacy `required_fields` of /account/payment_methods), with
   * State moved after Country. `requiredFields` comes from
   * `api.accountPaymentMethods(clientSecret)` (see fixtures/api.ts).
   */
  async testDynamicFields(
    customerData: CustomerData,
    requiredFields: Record<string, unknown>,
    testIdsToRemove: string[] = [],
    isThreeDSEnabled = false,
  ): Promise<void> {
    const mapping: Record<string, string> = {
      [testIds.cardNoInputTestId]: customerData.cardNo,
      [testIds.expiryInputTestId]: customerData.cardExpiry,
      [testIds.cardCVVInputTestId]: customerData.cardCVV,
      [testIds.fullNameInputTestId]: customerData.cardHolderName,
      [testIds.cardHolderNameInputTestId]: customerData.cardHolderName,
      [testIds.emailInputTestId]: customerData.email,
      [testIds.addressLine1InputTestId]: customerData.address,
      [testIds.cityInputTestId]: customerData.city,
      [testIds.countryDropDownTestId]: customerData.country,
      [testIds.stateDropDownTestId]: customerData.state,
      [testIds.postalCodeInputTestId]: customerData.postalCode,
    };
    if (isThreeDSEnabled)
      mapping[testIds.cardNoInputTestId] = customerData.threeDSCardNo;

    const fieldMap = testIds.fieldTestIdMapping as Record<string, string>;
    let ids = Object.keys(requiredFields)
      .map((k) => fieldMap[k])
      .filter((x): x is string => !!x);
    const countryIndex = ids.indexOf("Country");
    const stateIndex = ids.indexOf("State");
    if (countryIndex !== -1 && stateIndex !== -1 && stateIndex < countryIndex) {
      ids.splice(stateIndex, 1);
      ids.splice(countryIndex, 0, "State");
    }
    ids = [...new Set(ids)].filter((id) => !testIdsToRemove.includes(id));

    for (const id of ids) {
      const f = this.field(id);
      await expect(f).toBeVisible();
      if (id === "Country" || id === "State") {
        await f.selectOption(mapping[id]);
      } else {
        await f.pressSequentially(mapping[id] ?? "");
      }
    }
  }
}

