// SDK initialization: valid and invalid publishable keys and the extra
// initialization query params.
//
// Hermetic-capable: initialization only needs HyperLoader, the SDK iframes and
// the list calls (served from recordings/base in the hermetic tier).
//
// Note: the demo shop ignores the `customBackendUrl`
// and `isForceInit` query params (Hyperswitch-React-Demo-App/src/Payment.js
// only reads isTestMode, clientSecret, publishableKey, profileId,
// locale, theme, layout, options), so those two tests only prove the SDK still
// initialises with the extra params present.
import {
  test,
  expect,
  paymentBody,
  captureConsoleErrors,
  HYPERSWITCH_API_URL,
} from "../../fixtures";

const body = paymentBody({ customer_id: "sdk_init_test_user" });

test.describe("SDK Initialization Tests", () => {
  test("should initialize SDK with valid publishable key", async ({
    checkout,
    sdk,
  }) => {
    await checkout.open({ body });

    await sdk.waitForReady();
  });

  test("should fail initialization with invalid publishable key format", async ({
    checkout,
    page,
  }) => {
    const invalidKey = "invalid_key_format";

    // Registered before the SDK's JS runs, so early errors are captured.
    const consoleErrors = await captureConsoleErrors(page);
    await checkout.open({ body, publishableKey: invalidKey });

    await expect
      .poll(async () => (await consoleErrors()).length)
      .toBeGreaterThan(0);
  });

  test("should initialize with custom backend URL", async ({
    checkout,
    page,
    sdk,
  }) => {
    const customBackendUrl =
      process.env.HYPERSWITCH_CUSTOM_BACKEND_URL || HYPERSWITCH_API_URL;

    const intent = await checkout.createPaymentIntent(body);
    await page.goto(
      `${checkout.url(intent)}&customBackendUrl=${encodeURIComponent(customBackendUrl)}`,
    );

    await sdk.waitForReady();
  });

  test("should reinitialize SDK when isForceInit is true", async ({
    checkout,
    page,
    sdk,
  }) => {
    const intent = await checkout.createPaymentIntent(body);
    await page.goto(`${checkout.url(intent)}&isForceInit=true`);

    await sdk.waitForReady();

    expect(
      await page.evaluate(
        () => !!(window as unknown as { Hyper?: unknown }).Hyper,
      ),
    ).toBe(true);
  });

  test("should initialize SDK with profile ID", async ({ checkout, sdk }) => {
    // checkout.url() puts the intent's profile_id in the URL.
    await checkout.open({ body });

    await sdk.waitForReady();
  });
});

// Terms Display Tests: the `terms` option controls the visibility of terms text
// for different payment methods (Auto, Always, Never).
// Note: Card terms only display for mandate/setup flows (NEW_MANDATE/SETUP_MANDATE).
//
// Hermetic-capable. recordings/01-sdk-core/terms-display.json answers the
// client list with payment_type "new_mandate" for intents created with
// setup_future_usage=off_session (what the router does); other intents get the
// base "normal" list.
import { test, expect, paymentBody } from "../../fixtures";

const mandateBody = paymentBody({
  customer_id: "terms_test_user",
  authentication_type: "no_three_ds",
  setup_future_usage: "off_session",
});
// Same intent without setup_future_usage: a normal (non-mandate) payment.
const nonMandateBody = paymentBody({
  customer_id: "terms_test_user",
  authentication_type: "no_three_ds",
  setup_future_usage: undefined,
});

const termsOptions = (card: string) => ({
  terms: {
    card,
    auBecsDebit: "auto",
    bancontact: "auto",
    ideal: "auto",
    sepaDebit: "auto",
    sofort: "auto",
    usBankAccount: "auto",
  },
});

test.describe("PaymentElement terms Option", () => {
  test.describe('terms.card: "always" with mandate flow', () => {
    test.beforeEach(async ({ checkout }) => {
      await checkout.open({
        body: mandateBody,
        options: termsOptions("always"),
        waitForReady: true,
      });
    });

    test("should display card terms text when card is selected", async ({
      sdk,
    }) => {
      await expect(sdk.find(".TermsTextLabel").first()).toBeVisible({
        timeout: 10_000,
      });
    });
  });

  test.describe('terms.card: "never" with mandate flow', () => {
    test.beforeEach(async ({ checkout }) => {
      await checkout.open({
        body: mandateBody,
        options: termsOptions("never"),
        waitForReady: true,
      });
    });

    test("should hide card terms text when card is selected", async ({
      sdk,
    }) => {
      await expect(sdk.find(".TermsTextLabel")).toHaveCount(0);
    });
  });

  test.describe("terms.card: not applicable for non-mandate flow", () => {
    test.beforeEach(async ({ checkout }) => {
      await checkout.open({
        body: nonMandateBody,
        options: termsOptions("always"),
        waitForReady: true,
      });
    });

    test("should not show card terms for non-mandate payment flows", async ({
      sdk,
    }) => {
      await expect(sdk.find(".TermsTextLabel")).toHaveCount(0);
    });
  });
});

